recipe('ginger-tamari-fish-parcels','Ginger fish parcels with bok choy and rice',S,2,180,15,15,[[300,'hoki fillets','F001277','Two 150 g boneless pieces'],[30,'spring onion','F006250','Sliced'],[10,'red chilli','F002901','Sliced'],(5,'garlic','Grated'),(15,'ginger','Grated'),(30,'soy'),[8,'sesame oil','F006187'],(10,'honey'),[200,'bok choy','F001301','Separate leaves; thinly slice thick stems'],[250,'cooked brown rice','F007641','','cooked'],[5,'sesame seeds','F008214'],[10,'fresh coriander','F003192','Chopped'],(20,'lemon')],['Mix spring onion, chilli, garlic, ginger, soy, sesame oil, honey and lemon. Reserve half in a clean covered bowl before adding raw fish to the rest. Refrigerate fish for 30 minutes; discard excess raw-contact marinade.','Enclose fish in two securely folded, approved baking-paper parcels. Air fry at 180°C for 12 minutes, keeping paper away from the element. Open carefully, add bok choy and cook 3 minutes more until fish reaches 63°C.','Heat cooked rice thoroughly. Serve with fish, greens, clean reserved dressing, sesame seeds and coriander. Never drizzle marinade that touched raw fish over the cooked meal.'],'Fish steams in ginger-scented parcels with bok choy, then joins warm brown rice and a clean sesame dressing.',wait=30,internal=63,allergens=['fish','soy','wheat','gluten','sesame'],equipment=['Approved baking paper, securely folded into parcels'],nutritionNote='Soy sauce replaces tamari; wheat/gluten declared. Source four small portions become two meals with measured cooked rice. All marinade counted conservatively, although raw-contact excess is discarded.')
recipe('pork-souvlaki-skewers','Pork souvlaki with pita and cucumber yoghurt',M,4,180,20,20,[[600,'lean pork fillet','F006899','Cut into 2–3 cm cubes'],(20,'oil'),(3,'oregano'),(2,'cumin'),(2,'paprika'),(8,'garlic','Grated; half for dip'),(40,'lemon'),(10,'parsley','Chopped'),(240,'pita','Four 60 g breads'),(160,'yoghurt'),(100,'cucumber','Grated and squeezed'),(200,'freshTomato','Sliced')],['Coat pork cubes with oil, oregano, cumin, paprika, half the garlic and half the lemon. Thread loosely onto eight short skewers that fit the basket.','Air fry at 180°C for 20 minutes, turning after 10 minutes, until the thickest pork cubes reach 71°C. Rest for 3 minutes. Use two batches if skewers cannot sit apart; that adds 20 minutes.','Mix yoghurt, cucumber and remaining garlic and lemon. Fill pita breads with pork, tomato, parsley and the yoghurt sauce; remove all skewers before eating.'],'Small pork fillet skewers fill pita breads with tomato and a fresh cucumber yoghurt sauce.',wait=33,allergens=['wheat','gluten','milk'],equipment=['Eight short wooden skewers, soaked for 30 minutes'],nutritionNote='Pork and oil reduced to a basket-sized batch and all accompaniments quantified. Twenty-minute cooking assumes eight short skewers fit in a large basket in one spaced layer; additional batch time is explicit.')
recipe('roast-cauliflower-chickpea-chicken-salad','Chicken, roast cauliflower and chickpea salad',Q,4,200,20,40,[[300,'cooked skinless chicken breast','F002590','Shredded, kept chilled','cooked'],[80,'shallots','F008227','Peeled and halved'],(25,'garlic','Peeled whole cloves'),(1,'thyme'),[240,'canned chickpeas, drained','F002880','','canned'],(180,'capsicum','Cut into chunks'),[400,'cauliflower','F002378','Small florets'],(30,'oil','20 g for roasting; 10 g for dressing'),(50,'bread','Torn into small pieces'),[70,'rocket','F007712'],(20,'vinegar')],['Toss shallots, garlic and capsicum with half the roasting oil and thyme. Air fry at 200°C for 20 minutes, stirring halfway. Transfer to a shallow bowl and cool briefly.','Toss cauliflower and chickpeas with the other half of the roasting oil. Air fry at 200°C for 20 minutes, shaking halfway; add bread pieces for the final 5 minutes.','Mash roasted garlic with vinegar and the remaining 10 g oil. Combine warm vegetables, chickpeas and croutons with chilled cooked chicken and rocket. Dress and eat promptly.'],'Air-roasted cauliflower, chickpeas and croutons add crunch to shredded chicken and peppery leaves.',wait=5,internal=75,allergens=['wheat','gluten'],nutritionNote='Chicken is already cooked and served chilled; the cooked-chicken reference is used. Two sequential 20-minute vegetable batches are included. All oil is measured.',safety=['Keep the cooked chicken refrigerated until assembly. The 75°C reheating endpoint applies only if choosing to heat it; no raw chicken is used.'])
